import type { Fact, WalkStep } from '@/app/demos/stage/types'

export type EncodingKind = 'base64' | 'url' | 'html' | 'unicode' | 'hex'

export const KINDS: { id: EncodingKind; label: string }[] = [
  { id: 'base64', label: 'Base64' },
  { id: 'url', label: 'URL' },
  { id: 'html', label: 'HTML' },
  { id: 'unicode', label: 'Unicode' },
  { id: 'hex', label: 'Hex' },
]

const bytes = (input: string) => [...new TextEncoder().encode(input)]

/** The extension's encoders, so every output below is what the panel prints. */
export function encode(kind: EncodingKind, input: string): string {
  switch (kind) {
    case 'base64':
      return btoa(String.fromCharCode(...bytes(input)))
    case 'url':
      return encodeURIComponent(input)
    case 'html':
      return input
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;')
    case 'unicode':
      return [...input]
        .map((char) => {
          const code = char.codePointAt(0) ?? 0
          if (code <= 127) return char
          return code > 0xffff
            ? `\\u{${code.toString(16)}}`
            : `\\u${code.toString(16).padStart(4, '0')}`
        })
        .join('')
    case 'hex':
      return bytes(input)
        .map((byte) => byte.toString(16).padStart(2, '0'))
        .join('')
  }
}

export const TEXT = 'Ship it ☕ <now>'
export const OUTPUTS = KINDS.map((kind) => ({ ...kind, value: encode(kind.id, TEXT) }))
export const HEX = encode('hex', TEXT)
